<?php use CmuLms\View; $title='Before you begin'; include __DIR__.'/../layout/header.php'; ?>
<section class="hero"><span><?=View::e($exam['code'])?> · Secure assessment</span><h1><?=View::e($exam['title'])?></h1><p><?=View::e($exam['duration_minutes'])?> minutes · <?=View::e($exam['attempts_allowed'])?> attempts allowed</p></section>
<section class="card"><h2>Before you begin</h2><p>This assessment records your answers, submission time, IP address, browser/device details, focus events, and camera-based monitoring events for academic-integrity review. The disclosure version and acceptance time are recorded with your attempt.</p><form method="post" action="?route=exam-begin"><?=View::csrfField()?><input type="hidden" name="exam_id" value="<?=View::e($exam['id'])?>"><label><input type="checkbox" name="disclosure" value="1" required> I agree to the assessment disclosure and data-use statement.</label><label><input type="checkbox" name="honesty" value="1" required> I confirm this work is my own and I will follow the assessment rules.</label><?php if(!empty($exam['camera_required'])): ?><div class="card"><h3>Camera monitoring is required</h3><video id="previewCamera" autoplay muted playsinline style="width:260px;max-width:100%;border-radius:8px;background:#173f35"></video><p id="cameraMessage">Grant camera access before starting.</p><button type="button" id="grantCamera">Grant camera access</button><input type="hidden" name="camera_confirmed" id="cameraConfirmed" value="0"></div><?php endif; ?><button id="beginExam" type="submit" <?=!empty($exam['camera_required'])?'disabled':''?>>Start assessment</button></form></section>
<?php if(!empty($exam['camera_required'])): ?><script>const button=document.getElementById('grantCamera'),start=document.getElementById('beginExam'),confirmed=document.getElementById('cameraConfirmed'),message=document.getElementById('cameraMessage');let stream;button.addEventListener('click',()=>{if(!navigator.mediaDevices?.getUserMedia){message.textContent='This browser does not support camera access.';return}navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false}).then(s=>{stream=s;document.getElementById('previewCamera').srcObject=s;confirmed.value='1';start.disabled=false;message.textContent='Camera access granted. You may start.'}).catch(()=>{confirmed.value='0';start.disabled=true;message.textContent='Camera access is required. Allow it in the browser permission prompt.'})});</script><?php endif; ?>
